pub fn ledger(kinds: &[i64], amounts: &[i64], start: i64) -> i64 {
    let mut bal: i128 = start as i128;
    let max = i64::MAX as i128;
    for (k, a) in kinds.iter().zip(amounts.iter()) {
        let a = *a as i128;
        let mut ok = true;
        match *k {
            0 => {
                if bal + a > max {
                    ok = false;
                } else {
                    bal += a;
                }
            }
            1 => {
                if a > bal {
                    ok = false;
                } else {
                    bal -= a;
                }
            }
            2 => {
                let n = bal + (bal / 100) * a;
                if n > max {
                    ok = false;
                } else {
                    bal = n;
                }
            }
            3 => {
                bal -= a.min(bal);
            }
            _ => {}
        }
        if ok {
            println!("{}", bal as i64);
        } else {
            println!("{}", -1);
        }
    }
    bal as i64
}

