        assert_eq!(ledger(&[0, 1, 2, 3, 1], &[50, 500, 3, 10, 0], 100), 143);
        assert_eq!(ledger(&[2], &[i64::MAX], 1000), 1000);
        assert_eq!(ledger(&[0], &[1], i64::MAX), i64::MAX);
    }
}

pub fn report(a: &[i64], t: i64) -> i64 {
    if a.is_empty() {
        return 0;
    }
    let mn = *a.iter().min().unwrap();
    let mx = *a.iter().max().unwrap();
    let mid = ((mn as i128 + mx as i128) >> 1) as i64;
    let mut count: i64 = 0;
    let mut best: i64 = 0;
    let mut cur: i64 = 0;
    for &x in a {
        if x > t {
            count += 1;
            cur += 1;
            if cur > best {
                best = cur;
            }
        } else {
            cur = 0;
        }
    }
    println!("{}", mn);
    println!("{}", mx);
    println!("{}", mid);
    println!("{}", count);
    best
}

