        assert_eq!(report(&[], 0), 0);
        assert_eq!(report(&[1, 5, 6, 0, 7], 4), 2);
        assert_eq!(report(&[i64::MIN, i64::MIN + 1], 0), 0);
        assert_eq!(report(&[i64::MAX, i64::MAX], 0), 2);
