pub fn limiter(times: &[i64], cap: i64, every: i64) -> i64 {
    let mut tokens = cap;
    let mut mark: i64 = 0;
    let mut accepted = 0;
    for &t in times {
        let g = (t - mark) / every;
        if g > 0 {
            let room = cap - tokens;
            tokens += if g < room { g } else { room };
            mark += g * every;
        }
        if tokens >= 1 {
            tokens -= 1;
            accepted += 1;
            println!("1");
        } else {
            println!("0");
        }
    }
    accepted
}

