pub fn rle(a: &[i64], limit: i64) -> i64 {
    let limit = if limit < 1 { 1 } else { limit } as u128;
    let mut count: i64 = 0;
    let mut i = 0;
    while i < a.len() {
        let mut j = i;
        while j < a.len() && a[j] == a[i] {
            j += 1;
        }
        let mut rem = (j - i) as u128;
        while rem > 0 {
            let p = if rem > limit { limit } else { rem };
            println!("{}", a[i]);
            println!("{}", p);
            count += 1;
            rem -= p;
        }
        i = j;
    }
    count
}

